// For a watercolor-like effect, we need a realistic fluid simulation.
// This example uses a basic Lattice Boltzmann Method (LBM).
// For simplicity, all fluid properties are packed into a single texel as follows:
//   texel.r  -> packed color
//   texel.g  -> density
//   texel.ba -> velocity

// Note: We are not using the complete LBM solution with the 'Collision' step,
//       'Streaming' step, and 'Macroscopic' computations separately.
//       Instead, all steps are performed in a single step in Buffer C,
//       and the old distribution values are recalculated.


// Samples a pixel from iChannel0 and extracts its color and density.
// Then outputs a blend between white and that color based on density.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec4 pixel = texture(iChannel0, fragCoord / iResolution.xy);

    // Unpack color from iChannel0 at pixel coordinate space.
    vec3 color = getColor(iChannel0, fragCoord);

    // Clamp the density (stored in the 'G' component of pixel) to [0..1].
    float density = clamp(pixel.g, 0.0, 1.0);

    // Mix between white (1.0, 1.0, 1.0) and our color, using 'density' as the blend factor.
    fragColor = vec4(mix(vec3(1.0), color, density), 1.0);
}

vec4 drawCircle(vec4 fragColor, vec2 coord, vec2 center, float radius, vec3 color) {
    radius *= iResolution.x;
    float alpha = smoothstep(radius + 1.0, radius - 1.0, length(coord - center * iResolution.xy));
    if (alpha <= 0.0) {
        return fragColor;
    }

    vec4 noise = texture(iChannel3, coord / iChannelResolution[3].rg);
    alpha *= 1.0 - noise.r * CIRCLE_ROUGHNESS;

    vec2 velocityForTheLeft = vec2(1.0, (noise.g * 2.0 - 1.0) * 0.0) * 0.3; // move right
    vec2 velocityForTheRight = vec2(-1.0, (noise.g * 2.0 - 1.0) * 0.0) * 0.3; // move left
    float density = alpha;

    if (coord.x / iResolution.x < 0.5) {
        return vec4(packRGBColor(color), density, velocityForTheLeft.x, velocityForTheLeft.y); // moving right
    } else {
        return vec4(packRGBColor(color), density, velocityForTheRight.x, velocityForTheRight.y); // moving left
    }
}

// Main function to handle frame rendering
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame < 10) {
        // Draw two circles on a transparent background on the first frame
        fragColor = vec4(0.0, 0.0, 0.0, 0.0);
        fragColor = drawCircle(fragColor, fragCoord, vec2(0.41, 0.49), 0.08, vec3(0.9, 0.0, 0.0));
        fragColor = drawCircle(fragColor, fragCoord, vec2(0.59, 0.51), 0.08, vec3(0.0, 0.0, 0.9));
        // Or alternatively, load an image:
        // fragColor = vec4(packRGBColor(texture(iChannel3, fragCoord / iResolution.xy).rgb), texture(iChannel3, fragCoord / iResolution.xy).g, 0.0, 0.0);
    } else {
        // On subsequent frames, simply copy previously stored values
        // from Buffer B (iChannel1) into Buffer A (current buffer).
        // It is needed to calculate distribution for previous frame in Buffer C
        fragColor = getAllProperties(iChannel1, fragCoord);
    }
}

#define CIRCLE_ROUGHNESS 0.5
#define NOISE_SIZE       20.0
#define NOISE_STRENGTH   0.01
#define HIGH_DENSITY_ADVECTION_EASE_OUT 4.0

// Packs two floating-point values (expected in [0, 1]) into a single float.
float packFloats(vec2 ab) {
    int a = int(ab.x * 1023.0 + 0.5);
    int b = int(ab.y * 1023.0 + 0.5);
    return intBitsToFloat((a << 10) | b);
}

// Unpacks a single float (which encodes two 10-bit values) back into a vec2 in [0, 1].
vec2 unpackFloats(float packed) {
    int val = floatBitsToInt(packed);
    float x = float((val >> 10) & 1023) / 1023.0;
    float y = float(val & 1023)        / 1023.0;
    return vec2(x, y);
}

float packRGBColor(vec3 color) {
    return packFloats(color.rb);
}

vec4 getAllProperties(sampler2D channel, vec2 coord) {
    // If coord is already integral, ivec2(coord) is fine. Otherwise consider floor/round.
    return texelFetch(channel, ivec2(coord), 0);
}

float getDensity(sampler2D channel, vec2 coord) {
    return getAllProperties(channel, coord).g;
}

vec2 getVelocity(sampler2D channel, vec2 coord) {
    return getAllProperties(channel, coord).ba;
}

float getPackedColor(sampler2D channel, vec2 coord) {
    return getAllProperties(channel, coord).r;
}

vec3 getColor(sampler2D channel, vec2 coord) {
    vec2 redBlue = unpackFloats(getPackedColor(channel, coord));
    return vec3(redBlue.x, 0.0, redBlue.y);
}

// After this step, Buffer A contains properties from the previous frame,
// and Buffer B contains properties from the current frame.

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame < 10) {
        fragColor = getAllProperties(iChannel0, fragCoord);
    } else {
        fragColor = getAllProperties(iChannel1, fragCoord);
    }
}

// -----------------------------------------------------------------------------
// D2Q9 MODEL SETUP
// -----------------------------------------------------------------------------

// Lattice velocity vectors (offsets) in D2Q9 (2D, 9 directions).
// The first entry is stationary (0,0), followed by the four cardinal directions
// and then the four diagonals.
const vec2 offsets[9] = vec2[](
    vec2( 0.0,  0.0), // 0. Stationary
    vec2( 1.0,  0.0), // 1. East
    vec2( 0.0,  1.0), // 2. North
    vec2(-1.0,  0.0), // 3. West
    vec2( 0.0, -1.0), // 4. South
    vec2( 1.0,  1.0), // 5. Northeast
    vec2(-1.0,  1.0), // 6. Northwest
    vec2(-1.0, -1.0), // 7. Southwest
    vec2( 1.0, -1.0)  // 8. Southeast
);

// Corresponding weights for each D2Q9 direction.
const float weights[9] = float[](
    4.0 / 9.0,  // 0. Stationary
    1.0 / 9.0,  // 1. East
    1.0 / 9.0,  // 2. North
    1.0 / 9.0,  // 3. West
    1.0 / 9.0,  // 4. South
    1.0 / 36.0, // 5. Northeast
    1.0 / 36.0, // 6. Northwest
    1.0 / 36.0, // 7. Southwest
    1.0 / 36.0  // 8. Southeast
);

// Samples noise from texture channel iChannel3.
vec2 texNoise(vec2 coord) {
    return texture(iChannel3, coord / iChannelResolution[3].xy).rg;
}

// -----------------------------------------------------------------------------
// LATTICE BOLTZMANN FUNCTION
// -----------------------------------------------------------------------------

/**
 * Computes the equilibrium (Maxwell-Boltzmann) distribution function for
 * one of the D2Q9 directions given:
 *   - rho: density
 *   - u:   velocity
 *   - offset: one of the 9 discrete velocity directions
 *   - weight: the lattice weight associated with 'offset'
 *
 * Returns a scalar distribution value.
 */
float equilibrium(float rho, vec2 u, vec2 offset, float weight) {

    float dotProd = dot(offset, u);
    float uSq     = dot(u, u);

    // Example modification to amplify advection with higher densities:
    float velocityRho = 1.0 - pow(1.0 - rho, HIGH_DENSITY_ADVECTION_EASE_OUT); // ease out Rho for velocity part of equilibrium function

    // Standard LBM expression:
    //   f_eq = w * rho * [1 + 3(u·e) + 4.5(u·e)^2 - 1.5·u^2]

    return weight * rho // Velocity-Independent part
         + weight * velocityRho // Velocity-dependent part
           * (3.0 * dotProd + 4.5 * dotProd * dotProd - 1.5 * uSq);
}

// -----------------------------------------------------------------------------
// MAIN SHADER ENTRY POINT
// -----------------------------------------------------------------------------

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // On the first frame, simply copy the initial properties from iChannel0.
    if (iFrame < 10) {
        fragColor = getAllProperties(iChannel1, fragCoord);
    } else {
        // Collision relaxation factor (commonly denoted 1/tau).
        float tau = 0.5;

        // We'll accumulate final density, velocity, and color by streaming
        // from each of the 9 directions (offsets).
        float resultDensity   = 0.0;
        vec2  resultVelocity  = vec2(0.0);
        vec3  resultColor     = vec3(0.0);

        // For each direction in D2Q9...
        for (int i = 0; i < 9; i++) {
            // Retrieve old velocity/density from iChannel0.
            vec2 oldVelocity = getVelocity(iChannel0, fragCoord - offsets[i]);
            float oldDensity = getDensity(iChannel0, fragCoord - offsets[i]);

            // Compute the old equilibrium distribution for that neighbor cell.
            float oldEquilibrium = equilibrium(oldDensity, oldVelocity, offsets[i], weights[i]);

            // Retrieve current velocity/density/color.
            float currentDensity = getDensity(iChannel1,  fragCoord - offsets[i]);
            vec2  currentVelocity = getVelocity(iChannel1, fragCoord - offsets[i]);
            vec3  currentColor    = getColor(iChannel1,    fragCoord - offsets[i]);

            // Compute the new equilibrium distribution for that neighbor cell.
            float newEquilibrium = equilibrium(currentDensity, currentVelocity, offsets[i], weights[i]);

            // Relaxation (collision step): blend old & new equilibrium distributions.
            float relaxedEquilibrium = mix(oldEquilibrium, newEquilibrium, tau);

            // Stream & accumulate into our result cell.
            resultDensity  += relaxedEquilibrium;
            resultVelocity += offsets[i] * relaxedEquilibrium;
            resultColor    += relaxedEquilibrium * currentColor;
        }

        // Add small random perturbation to the velocity for turbulence-like effect.
        resultVelocity += (texNoise(fragCoord / NOISE_SIZE) - 0.5) * NOISE_STRENGTH;

        // Clamp the velocity to avoid blow-up or extreme speeds.
        resultVelocity = clamp(resultVelocity, -0.5, 0.5);

        // Normalize color by density, if we have nonzero density.
        if (resultDensity != 0.0) {
            resultColor /= resultDensity;
        }

        // Ensure color stays within [0..1].
        resultColor = clamp(resultColor, 0.0, 1.0);

        // Pack our final properties into a vec4:
        //   R = packed color (only R and B channels are stored)
        //   G = density
        //   B = velocity.x
        //   A = velocity.y
        fragColor = vec4(
            packRGBColor(resultColor),
            resultDensity,
            resultVelocity.x,
            resultVelocity.y
        );
    }
}
